function download(name:string,content:string,type='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function csv(rows:any[]){if(!rows.length)return '';const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];return [keys.join(','),...rows.map(r=>keys.map(k=>JSON.stringify(r[k]??'')).join(','))].join('\n')}
function parseCsv(s:string){const lines=s.replace(/\r/g,'').split('\n').filter(Boolean);if(!lines.length)return [];const parse=(line:string)=>{const out:string[]=[];let v='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&q){v+='"';i++;}else if(c==='"')q=!q;else if(c===','&&!q){out.push(v);v='';}else v+=c;}out.push(v);return out;};const h=parse(lines[0]).map(x=>x.trim());return lines.slice(1).map(line=>Object.fromEntries(parse(line).map((v,i)=>[h[i]||`column_${i+1}`,v])));}
