 async function removeDemoWorkspace(){if(!supabase||!user)return;const ids=JSON.parse(localStorage.getItem('trading-erp-demo-'+user.id)||'[]');if(!ids.length){setMessage('No demo batch is registered in this browser. Delete demo-labelled records from their module tables.');return;}if(!confirm('Delete all sample records created by the demo setup? Your own records will not be touched.'))return;setBusy(true);for(const x of [...ids].reverse()){const owner=x.table==='brokers'?'owner_id':'user_id';await supabase.from(x.table).delete().eq('id',x.id).eq(owner,user.id);}localStorage.removeItem('trading-erp-demo-'+user.id);await load();setBusy(false);setMessage('Demo sample records removed.');}

 if(!session)return <main className="auth"><div className="auth-card"><div className="brand-mark">TE</div><p className="eyebrow">TRADING OPERATIONS PLATFORM</p><h1>Trading ERP</h1><p className="muted">A disciplined command centre for multi-asset trading.</p><form onSubmit={signIn}><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={8}/></label><button className="primary">Sign in</button></form><button className="text-button" onClick={signUp}>Create account (admin approval required)</button>{message&&<p className="notice">{message}</p>}</div></main>;
